"""Рядок 157, її річ СЛОВАМИ поза сценарієм. (1) Куди йде репліка (`річ_з_фото.довідка_репліка`) і що код
закріплює: фраза «Ір», 8 речень повернення куратора (заперечення, чужа річ, питання). (2) Модель змовчала / повторний хід.
(3) Закріплена річ словами × 3 сценарії, неслухняна модель руки 1: частка образів із річчю (має бути 100 %),
з другою річчю в її слоті (0), колір у вердикті — «без входу». Запуск із `джерела`: python3 проби/richi_slovamy_157.py"""
import json, sys, itertools; sys.path.insert(0, '.'); import bridge as B, річ_з_фото as Р; from міст_річ import судження
# (фраза, чи йде в сценарій, що закріплює код) — 8 речень повернення куратора 24.09 + Ір і контроль
ФРАЗИ = [("В мене світлі джинси кльош від коліна. Врахуй їх при побудові образу", 1, "низ"),
         ("Мені не подобаються мої джинси, хочу щось інше.", 0, None), ("Моя сестра подарувала мені сукню, але я її не ношу.", 0, None),
         ("Іду в театр. Свої кросівки не беру, потрібні туфлі.", 0, None), ("На роботу. Хочу, щоб мої ноги виглядали довшими — може, штани зі стрілками?", 1, None),
         ("Моя подруга носить джинси кльош, а мені підійдуть?", 0, None), ("У мене немає джинсів, що порадиш?", 0, None),
         ("Чому в образі стоять джинси, а не спідниця?", 0, None), ("У мене в шафі багато светрів", 0, None),
         ("Хочу в образі оригінальну чи вінтажну біжутерію, екосумку", 1, None), ("У мене є чорне пальто, з чим його носити?", 1, "верхній_шар"),
         ("Моя улюблена сукня — червона, хочу її вдягнути", 1, "сукня"), ("Що означає ошатність?", 0, None), ("навіщо обхват голови?", 0, None)]
хибних_маршрутів = хибних_закріплень = 0
for ф, куди, слот in ФРАЗИ:
    к = Р.довідка_репліка(ф); сл = Р.речі_словами(ф); з = Р.речі_з_json([], [], словами=сл)
    хибних_маршрутів += к['до_сценарію'] != bool(куди); хибних_закріплень += [р['слот'] for р in з] != ([слот] if слот else [])
    print('%-4s %-56s → %s' % ('СЦЕН' if к['до_сценарію'] else 'пом.', ф[:56], '; '.join(Р.звіт_словами(сл, з)) or к['чому'][:70]))
print('хибних маршрутів: %d, хибних закріплень: %d (із %d фраз)' % (хибних_маршрутів, хибних_закріплень, len(ФРАЗИ)))
сл = Р.речі_словами(ФРАЗИ[0][0])
модель = [dict(фото=None, назва='світлі джинси кльош', слот='низ', колір='блакитний', чия='моя')]
досі = Р.речі_з_json(модель, None, None, словами=сл); print('модель змовчала: %s' % [(x['ід'], x['назва'], x['колір']) for x in Р.речі_з_json([], None, None, словами=сл)])
print('другий хід: речей %d; потім «Мені не подобаються мої джинси» → речей %d' % (len(Р.речі_з_json(модель, None, досі, словами=сл)),
      len(Р.речі_з_json([], None, досі, словами=Р.речі_словами(ФРАЗИ[0][0] + ' ' + ФРАЗИ[1][0])))))
вх = json.load(open('стенд_вх.json'))
СЦ = [dict(нагода='робота', місце='офіс_корпоративний', година=10, темп_c=18), dict(нагода='побачення', місце='ресторан_районний',
      година=19, темп_c=14), dict(нагода='щоденне', місце='парк', година=15, темп_c=5, опади='дощ')]
з_річчю = всього = друга = 0; колір = set()
for (мітка, сирі), сц in itertools.product((('з кольором', модель), ('без кольору', [])), СЦ):
    річ = Р.речі_з_json(сирі, None, None, словами=сл)[0]
    д = dict(вх, сценарій=сц, паспорт=dict(сц, речі_з_фото=[річ]), варіантів=10, бюджет_символів=120000, без_фото=1)
    пул = json.loads(json.loads(B.виклик('запити', json.dumps(д, ensure_ascii=False)))['руки']['1'])['пул']
    н = lambda с, i: пул[с][i % len(пул[с])]['н'] if пул.get(с) else None
    обр = [dict(ід='о%d' % i, речі=[x for x in [н('верх', i), н('низ', i), н('взуття', i), н('сумка', i), н('шарф', i) or н('сережки', i)] if x]) for i in range(1, 5)]
    for о in json.loads(B.виклик('від_моделі', json.dumps(dict(д, текст_моделі=json.dumps(dict(версія='1', образи=обр), ensure_ascii=False)), ensure_ascii=False))).get('образи') or []:
        всього += 1; з_річчю += 'її-с1' in о['ід']; друга += sum(с in Р.займає('низ') for с in (о.get('слоти_н') or {}).values()) > 1
    в = судження(д)(річ); колір |= {x for x in (в.get('чекліст') or {}).get('без_входу') or [] if x.startswith('колір')}
    print('%s · %s: вердикт «%s»' % (мітка, сц['нагода'], (в.get('рядок') or '')[:150]))
print('образів руки 1: %d, з її річчю %d (%.0f %%), з другою річчю в її слоті %d' % (всього, з_річчю, 100 * з_річчю / max(1, всього), друга))
print('колір у «без входу»: %s' % sorted(колір))
